@dataclass(frozen=True)
class RemoteVNCTarget:
    """One immutable, loopback-only VNC target registered to a session."""

    host: str
    port: int
    source: str = "configured"
    runtime_id: str = ""
    generation: str = ""


@dataclass
class ManagedWebPreview:
    process: subprocess.Popen[Any]
    entry: str
    workspace: Path
    script: str
    log_path: Path
    # A managed preview is an in-process capability, not a durable endpoint.
    # Persist this nonce alongside the container/runtime epoch so a loopback
    # port left in state.json can never be trusted after the owning process is
    # gone (or after the port has been reused by an unrelated local service).
    generation: str = ""

    def ready(self) -> bool:
        return self.process.poll() is None

    def stop(self) -> None:
        if self.process.poll() is not None:
            return
        with contextlib.suppress(OSError):
            self.process.terminate()
        try:
            self.process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            with contextlib.suppress(OSError):
                self.process.kill()
            with contextlib.suppress(subprocess.TimeoutExpired):
                self.process.wait(timeout=5)


@dataclass(frozen=True)
class RemoteDisplayLauncher:
    """One server-selected display launcher with an immutable argv vector.

    Browser requests select only an already-declared experience surface.  They
    never supply an executable, arguments, working directory, port, or shell
    fragment.  Keeping the complete argv here makes that boundary explicit.
    """

    provider: str
    label: str
    argv: tuple[str, ...]
    target: RemoteVNCTarget


def load_private_config(path: Path) -> dict[str, Any]:
    """Load one local-only configuration file without requiring it to exist."""

    resolved = path.expanduser().resolve(strict=False)
    if not resolved.exists():
        return {}
    try:
        value = json.loads(resolved.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RuntimeError(f"Private config is invalid: {resolved}") from exc
    if not isinstance(value, dict):
        raise RuntimeError(f"Private config must contain a JSON object: {resolved}")
    version = value.get("schema_version", PRIVATE_CONFIG_SCHEMA_VERSION)
    if version != PRIVATE_CONFIG_SCHEMA_VERSION:
        raise RuntimeError(f"Unsupported private config schema_version: {version}")
    return value


def save_private_config(path: Path, value: dict[str, Any]) -> None:
    """Atomically save local settings such as reversible network changes."""

    resolved = path.expanduser().resolve(strict=False)
    resolved.parent.mkdir(parents=True, exist_ok=True)
    temporary = resolved.with_name(f".{resolved.name}.{uuid.uuid4().hex}.tmp")
    temporary.write_text(
        json.dumps(value, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    os.replace(temporary, resolved)
    with contextlib.suppress(OSError):
        resolved.chmod(0o600)


def _fernet_private_secret_cipher():
    """Return a host-local Fernet cipher backed by a mode-0600 key file."""

    from cryptography.fernet import Fernet

    configured = str(os.environ.get("WF_PRIVATE_SECRET_KEY_FILE") or "").strip()
    if configured:
        key_path = Path(configured).expanduser().resolve(strict=False)
    else:
        agent_home = Path(
            str(os.environ.get("WF_AGENT_HOME") or (Path.home() / ".applooper"))
        ).expanduser().resolve(strict=False)
        key_path = agent_home / "private-secret-fernet.key"
    key_path.parent.mkdir(parents=True, exist_ok=True)
    if not key_path.exists():
        key = Fernet.generate_key()
        try:
            descriptor = os.open(
                key_path,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL,
                0o600,
            )
        except FileExistsError:
            pass
        else:
            with os.fdopen(descriptor, "wb") as handle:
                handle.write(key + b"\n")
                handle.flush()
                os.fsync(handle.fileno())
    key = key_path.read_bytes().strip()
    with contextlib.suppress(OSError):
        key_path.chmod(0o600)
    return Fernet(key)


def protect_private_secret(value: str) -> str:
    """Protect a local secret with DPAPI or a host-local Fernet key."""

    text = str(value or "")
    if not text:
        raise ValueError("secret cannot be empty")
    use_fernet = os.name != "nt" or str(
        os.environ.get("WF_PRIVATE_SECRET_BACKEND") or ""
    ).strip().casefold() == "fernet"
    if use_fernet:
        token = _fernet_private_secret_cipher().encrypt(text.encode("utf-8"))
        return "fernet-v1:" + token.decode("ascii")

    import ctypes
    from ctypes import wintypes

    class DataBlob(ctypes.Structure):
        _fields_ = [("cbData", wintypes.DWORD), ("pbData", ctypes.POINTER(ctypes.c_ubyte))]

    raw = text.encode("utf-8")
    raw_buffer = ctypes.create_string_buffer(raw)
    source = DataBlob(len(raw), ctypes.cast(raw_buffer, ctypes.POINTER(ctypes.c_ubyte)))
    protected = DataBlob()
    crypt32 = ctypes.WinDLL("crypt32", use_last_error=True)
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    if not crypt32.CryptProtectData(
        ctypes.byref(source),
        "AppLooper project secret",
        None,
        None,
        None,
        0x1,
        ctypes.byref(protected),
    ):
        raise OSError(ctypes.get_last_error(), "Windows DPAPI could not protect the project secret")
    try:
        payload = ctypes.string_at(protected.pbData, protected.cbData)
    finally:
        kernel32.LocalFree(protected.pbData)
    return "dpapi:" + base64.urlsafe_b64encode(payload).decode("ascii")


def unprotect_private_secret(value: str) -> str:
    """Unprotect one local value without placing it in public app state."""

    encoded = str(value or "")
    if encoded.startswith("fernet-v1:"):
        from cryptography.fernet import InvalidToken

        try:
            payload = _fernet_private_secret_cipher().decrypt(
                encoded.removeprefix("fernet-v1:").encode("ascii")
            )
        except (InvalidToken, UnicodeEncodeError) as exc:
            raise ValueError("invalid protected secret payload") from exc
        return payload.decode("utf-8")
    if not encoded.startswith("dpapi:"):
        raise ValueError("unsupported protected secret format")
    if os.name != "nt":
        raise RuntimeError("DPAPI-protected project secrets can only be opened on Windows")

    import ctypes
    from ctypes import wintypes

    class DataBlob(ctypes.Structure):
        _fields_ = [("cbData", wintypes.DWORD), ("pbData", ctypes.POINTER(ctypes.c_ubyte))]

    try:
        raw = base64.urlsafe_b64decode(encoded.removeprefix("dpapi:").encode("ascii"))
    except (ValueError, UnicodeEncodeError) as exc:
        raise ValueError("invalid protected secret payload") from exc
    raw_buffer = ctypes.create_string_buffer(raw)
    source = DataBlob(len(raw), ctypes.cast(raw_buffer, ctypes.POINTER(ctypes.c_ubyte)))
    plain = DataBlob()
    crypt32 = ctypes.WinDLL("crypt32", use_last_error=True)
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    if not crypt32.CryptUnprotectData(
        ctypes.byref(source),
        None,
        None,
        None,
        None,
        0x1,
        ctypes.byref(plain),
    ):
        raise OSError(ctypes.get_last_error(), "Windows DPAPI could not unprotect the project secret")
    try:
        payload = ctypes.string_at(plain.pbData, plain.cbData)
    finally:
        kernel32.LocalFree(plain.pbData)
    return payload.decode("utf-8")


@dataclass(frozen=True)
class PreviewTransformCacheEntry:
    """One final, safe-to-relay transformed static representation."""

    body: bytes
    content_type: str
    content_language: str
    content_encoding: str
    vary_accept_encoding: bool
    etag: str
    stored_at: float


class PreviewTransformCache:
    """Small process-local LRU for expensive Preview rewrites and gzip.

    Capability authorization and loopback target validation deliberately stay
    outside this cache and run before every lookup.  Entries contain only
    complete, successful static responses; documents, APIs, redirects, errors
    and ranges never reach ``put``.
    """

    def __init__(
        self,
        *,
        max_bytes: int = PREVIEW_TRANSFORM_CACHE_MAX_BYTES,
        max_items: int = PREVIEW_TRANSFORM_CACHE_MAX_ITEMS,
        ttl_seconds: float = PREVIEW_STATIC_CACHE_SECONDS,
        max_entry_bytes: int = PREVIEW_TRANSFORM_CACHE_MAX_ENTRY_BYTES,
    ):
        self.max_bytes = max(1, int(max_bytes))
        self.max_items = max(1, int(max_items))
        self.ttl_seconds = max(0.001, float(ttl_seconds))
        self.max_entry_bytes = max(1, min(int(max_entry_bytes), self.max_bytes))
        self._lock = threading.RLock()
        self._items: collections.OrderedDict[
            PreviewTransformCacheKey, PreviewTransformCacheEntry
        ] = collections.OrderedDict()
        self._bytes = 0

    def _remove_locked(self, key: PreviewTransformCacheKey) -> None:
        removed = self._items.pop(key, None)
        if removed is not None:
            self._bytes -= len(removed.body)

    def get(
        self,
        key: PreviewTransformCacheKey,
        *,
        now: float | None = None,
    ) -> PreviewTransformCacheEntry | None:
        current = time.monotonic() if now is None else float(now)
        with self._lock:
            entry = self._items.get(key)
            if entry is None:
                return None
            if current - entry.stored_at >= self.ttl_seconds:
                self._remove_locked(key)
                return None
            self._items.move_to_end(key)
            return entry

    def put(self, key: PreviewTransformCacheKey, entry: PreviewTransformCacheEntry) -> bool:
        size = len(entry.body)
        if size > self.max_entry_bytes or size > self.max_bytes:
            return False
        with self._lock:
            self._remove_locked(key)
            self._items[key] = entry
            self._bytes += size
            while len(self._items) > self.max_items or self._bytes > self.max_bytes:
                oldest = next(iter(self._items))
                self._remove_locked(oldest)
        return True

    def clear(self) -> None:
        with self._lock:
            self._items.clear()
            self._bytes = 0

    def __len__(self) -> int:
        with self._lock:
            return len(self._items)


_PREVIEW_HTML_ATTRIBUTE_RE = re.compile(
    r"(?P<head>\b(?:src|href|poster|data|action)\s*=\s*)"
    r"(?P<quote>['\"])(?P<url>/(?!/)[^'\"]*)(?P=quote)",
    re.IGNORECASE,
)
_PREVIEW_HTML_UNQUOTED_ATTRIBUTE_RE = re.compile(
    r"(?P<head>\b(?:src|href|poster|data|action)\s*=\s*)"
    r"(?P<url>/(?!/)[^\s'\"`=<>]+)",
    re.IGNORECASE,
)
_PREVIEW_HTML_SCRIPT_RE = re.compile(
    r"(?P<open><script\b[^>]*>)(?P<body>.*?)(?P<close></script\s*>)",
    re.IGNORECASE | re.DOTALL,
)
_PREVIEW_HTML_STYLE_RE = re.compile(
    r"(?P<open><style\b[^>]*>)(?P<body>.*?)(?P<close></style\s*>)",
    re.IGNORECASE | re.DOTALL,
)
_PREVIEW_JS_FROM_ROOT_RE = re.compile(
    r"(?P<head>\bfrom\s*)(?P<quote>['\"])(?P<url>/(?!/)[^\s'\"<>]*)(?P=quote)"
)
_PREVIEW_JS_IMPORT_ROOT_RE = re.compile(
    r"(?P<head>\bimport\s*)(?P<quote>['\"])(?P<url>/(?!/)[^\s'\"<>]*)(?P=quote)"
)
_PREVIEW_JS_DYNAMIC_IMPORT_ROOT_RE = re.compile(
    r"(?P<head>\bimport\s*\(\s*)(?P<quote>['\"])(?P<url>/(?!/)[^\s'\"<>]*)(?P=quote)"
)
_PREVIEW_JS_NEW_URL_ROOT_RE = re.compile(
    r"(?P<head>\bnew\s+(?:URL|Worker|SharedWorker)\s*\(\s*)"
    r"(?P<quote>['\"])(?P<url>/(?!/)[^\s'\"<>]*)(?P=quote)"
)
_PREVIEW_CSS_URL_RE = re.compile(
    r"(?P<head>url\(\s*)(?P<quote>['\"]?)(?P<url>/(?!/)[^)'\"]*)"
    r"(?P=quote)(?P<tail>\s*\))",
    re.IGNORECASE,
)
_PREVIEW_CSS_IMPORT_RE = re.compile(
    r"(?P<head>@import\s+)(?P<quote>['\"])(?P<url>/(?!/)[^'\"]*)"
    r"(?P=quote)",
    re.IGNORECASE,
)

_PREVIEW_SANDBOX_STORAGE_SHIM = """<script data-applooper-preview-shim>
(()=>{"use strict";
const proxyPrefix=__APPLOOPER_PROXY_PREFIX__,originRoot=proxyPrefix+"/__applooper_origin_root__";
const mapUrl=value=>typeof value==="string"&&value.startsWith("/")&&!value.startsWith("//")&&!value.startsWith(proxyPrefix+"/")?originRoot+value:value;
const make=()=>{const data=new Map();return{get length(){return data.size},clear(){data.clear()},getItem(key){key=String(key);return data.has(key)?data.get(key):null},key(index){return [...data.keys()][Number(index)]??null},removeItem(key){data.delete(String(key))},setItem(key,value){data.set(String(key),String(value))}}};
const states=[];
for(const name of["localStorage","sessionStorage"]){let usable=false;try{const storage=window[name],probe="__applooper_preview_probe__";storage.setItem(probe,"1");storage.removeItem(probe);usable=true}catch(error){states.push(name+":native-"+error.name)}if(!usable){try{Object.defineProperty(window,name,{configurable:true,enumerable:true,value:make()});states.push(name+":memory")}catch(error){states.push(name+":failed-"+error.name)}}}
if(typeof window.fetch==="function"){const nativeFetch=window.fetch.bind(window);window.fetch=(input,init)=>nativeFetch(typeof input==="string"?mapUrl(input):input,init)}
if(window.XMLHttpRequest){const nativeOpen=XMLHttpRequest.prototype.open;XMLHttpRequest.prototype.open=function(method,url,...rest){return nativeOpen.call(this,method,mapUrl(url),...rest)}}
for(const name of["pushState","replaceState"]){const nativeHistory=history[name].bind(history);history[name]=(state,title,url)=>nativeHistory(state,title,mapUrl(url))}
const rewriteElement=element=>{for(const name of["src","href","poster","action"]){const value=element.getAttribute?.(name);if(value){const mapped=mapUrl(value);if(mapped!==value)element.setAttribute(name,mapped)}}};
new MutationObserver(records=>{for(const record of records){if(record.type==="attributes")rewriteElement(record.target);for(const node of record.addedNodes||[]){if(node.nodeType===1){rewriteElement(node);node.querySelectorAll?.("[src],[href],[poster],[action]").forEach(rewriteElement)}}}}).observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:["src","href","poster","action"]});
document.documentElement.dataset.applooperPreviewStorage=states.join(",");
const announceReady=()=>window.parent?.postMessage({type:"applooper-preview-ready"},"*");if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",announceReady,{once:true});else queueMicrotask(announceReady);
window.addEventListener("error",event=>{document.documentElement.dataset.applooperPreviewError=(String(event.message||"script error")+" @ "+String(event.filename||"")+":"+String(event.lineno||0)+":"+String(event.colno||0)).slice(0,500)});
window.addEventListener("unhandledrejection",event=>{document.documentElement.dataset.applooperPreviewError=String(event.reason||"unhandled rejection").slice(0,300)});
})();
</script>"""
_PREVIEW_HEAD_RE = re.compile(r"(<head\b[^>]*>)", re.IGNORECASE)


def _preview_capability_root_url(value: str, proxy_prefix: str) -> str:
    """Keep one upstream root URL beneath the opaque Preview capability.

    This intentionally accepts only literal, same-origin root paths.  Network
    and protocol-relative URLs remain untouched; malformed root paths are
    quarantined below the capability instead of being allowed to escape it.
    """

    if not value.startswith("/") or value.startswith("//"):
        return value
    if value.startswith(proxy_prefix + "/") or value == proxy_prefix:
        return value
    try:
        parsed = urllib.parse.urlsplit(value)
        decoded_parts = urllib.parse.unquote(parsed.path).split("/")
        unsafe = (
            bool(parsed.scheme or parsed.netloc)
            or "\\" in value
            or any(char.isspace() or ord(char) < 32 for char in value)
            or (len(value) > 1 and value[1] in "<>{}*")
            or any(part in {".", ".."} for part in decoded_parts)
        )
    except ValueError:
        unsafe = True
    if unsafe:
        return f"{proxy_prefix}/{PREVIEW_PROXY_ROOT_MARKER}/__invalid_preview_path__"
    return f"{proxy_prefix}/{PREVIEW_PROXY_ROOT_MARKER}{value}"


def _rewrite_preview_javascript(text: str, proxy_prefix: str) -> str:
    def replace(match: re.Match[str]) -> str:
        value = match.group("url")
        rewritten = _preview_capability_root_url(value, proxy_prefix)
        return f"{match.group('head')}{match.group('quote')}{rewritten}{match.group('quote')}"

    for pattern in (
        _PREVIEW_JS_FROM_ROOT_RE,
        _PREVIEW_JS_IMPORT_ROOT_RE,
        _PREVIEW_JS_DYNAMIC_IMPORT_ROOT_RE,
        _PREVIEW_JS_NEW_URL_ROOT_RE,
    ):
        text = pattern.sub(replace, text)
    # Vite commonly emits CSS as JavaScript string literals before injecting
    # it into a style element.  Reuse the deliberately narrow CSS root rules
    # so url(/asset) and @import "/asset" cannot escape the capability path;
    # unrelated JavaScript strings such as client-side routes stay untouched.
    return _rewrite_preview_css(text, proxy_prefix)


def _rewrite_preview_css(text: str, proxy_prefix: str) -> str:
    def replace_url(match: re.Match[str]) -> str:
        rewritten = _preview_capability_root_url(match.group("url"), proxy_prefix)
        return (
            f"{match.group('head')}{match.group('quote')}{rewritten}"
            f"{match.group('quote')}{match.group('tail')}"
        )

    def replace_import(match: re.Match[str]) -> str:
        rewritten = _preview_capability_root_url(match.group("url"), proxy_prefix)
        return f"{match.group('head')}{match.group('quote')}{rewritten}{match.group('quote')}"

    return _PREVIEW_CSS_IMPORT_RE.sub(replace_import, _PREVIEW_CSS_URL_RE.sub(replace_url, text))


def _owner_trial_seed_from_query(query: str) -> dict[str, Any] | None:
    """Parse a bounded owner-verify seed from the Preview query string."""

    if not query:
        return None
    try:
        params = urllib.parse.parse_qs(query, keep_blank_values=False)
        raw = str((params.get("applooper_owner_seed") or [""])[0] or "").strip()
        if not raw:
            return None
        padding = "=" * (-len(raw) % 4)
        payload = json.loads(base64.urlsafe_b64decode(raw + padding).decode("utf-8"))
    except (ValueError, json.JSONDecodeError, UnicodeError):
        return None
    if not isinstance(payload, dict):
        return None
    ensure_logs = max(0, min(5, int(payload.get("ensure_logs") or 0)))
    focus_id = re.sub(r"[^A-Za-z0-9_-]", "", str(payload.get("focus_id") or ""))[:64]
    storage_key = re.sub(
        r"[^A-Za-z0-9_-]", "", str(payload.get("storage_key") or "hydration_app_v1")
    )[:64] or "hydration_app_v1"
    return {
        "version": 1,
        "ensure_logs": ensure_logs,
        "focus_id": focus_id,
        "storage_key": storage_key,
    }


_OWNER_TRIAL_SEED_SCRIPT = """<script data-applooper-owner-seed>
(()=>{"use strict";
const seed=__APPLOOPER_OWNER_SEED__;
try{
  const key=String(seed.storage_key||"hydration_app_v1");
  const need=Math.max(0,Math.min(5,Number(seed.ensure_logs||0)));
  const pad=n=>String(n).padStart(2,"0");
  // Match the water app's getTodayKey(): UTC ISO date slice.
  const today=new Date().toISOString().slice(0,10);
  let raw={};try{raw=JSON.parse(localStorage.getItem(key)||"{}")||{}}catch(_e){raw={}}
  if(!raw.days||typeof raw.days!=="object")raw.days={};
  let day=raw.days[today];if(!day||typeof day!=="object")day={count:0,logs:[],goal:8};
  if(day.goal==null||!(Number(day.goal)>0))day.goal=8;
  if(!Array.isArray(day.logs))day.logs=[];
  while(day.logs.length<need){
    const now=new Date();
    day.logs.push({time:pad(now.getHours())+":"+pad(now.getMinutes()),ts:now.getTime()-day.logs.length*60000});
  }
  if(need>0){day.count=Math.max(Number(day.count||0),day.logs.length);raw.days[today]=day;localStorage.setItem(key,JSON.stringify(raw));}
}catch(_err){}
const focus=()=>{
  const id=String(seed.focus_id||"");
  if(!id)return;
  const node=document.getElementById(id);
  if(!node)return;
  try{node.scrollIntoView({block:"center",behavior:"smooth"});}catch(_e){try{node.scrollIntoView(true);}catch(_e2){}}
  node.style.outline="3px solid #e3a21a";
  node.style.outlineOffset="3px";
};
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",()=>setTimeout(focus,80),{once:true});
else setTimeout(focus,80);
})();
</script>"""


def _rewrite_preview_html(
    text: str,
    proxy_prefix: str,
    *,
    owner_seed: dict[str, Any] | None = None,
) -> str:
    def replace_attribute(match: re.Match[str]) -> str:
        rewritten = _preview_capability_root_url(match.group("url"), proxy_prefix)
        quote = match.groupdict().get("quote") or ""
        return f"{match.group('head')}{quote}{rewritten}{quote}"

    def replace_script(match: re.Match[str]) -> str:
        return (
            match.group("open")
            + _rewrite_preview_javascript(match.group("body"), proxy_prefix)
            + match.group("close")
        )

    def replace_style(match: re.Match[str]) -> str:
        return (
            match.group("open")
            + _rewrite_preview_css(match.group("body"), proxy_prefix)
            + match.group("close")
        )

    # A sandbox without allow-same-origin deliberately cannot access the
    # browser's persistent storage.  Many ordinary SPAs read localStorage at
    # bootstrap, so provide an isolated, refresh-scoped implementation rather
    # than weakening the iframe and exposing AppLooper's authenticated origin.
    sandbox_shim = _PREVIEW_SANDBOX_STORAGE_SHIM.replace(
        "__APPLOOPER_PROXY_PREFIX__",
        json.dumps(proxy_prefix, ensure_ascii=True),
    )
    seed_shim = ""
    if isinstance(owner_seed, dict) and owner_seed:
        seed_shim = _OWNER_TRIAL_SEED_SCRIPT.replace(
            "__APPLOOPER_OWNER_SEED__",
            json.dumps(owner_seed, ensure_ascii=True),
        )
    head_inject = sandbox_shim + seed_shim
    if _PREVIEW_HEAD_RE.search(text):
        text = _PREVIEW_HEAD_RE.sub(r"\1" + head_inject, text, count=1)
    else:
        text = head_inject + text

    rewritten = _PREVIEW_HTML_ATTRIBUTE_RE.sub(replace_attribute, text)
    rewritten = _PREVIEW_HTML_UNQUOTED_ATTRIBUTE_RE.sub(replace_attribute, rewritten)
    rewritten = _PREVIEW_HTML_SCRIPT_RE.sub(replace_script, rewritten)
    return _PREVIEW_HTML_STYLE_RE.sub(replace_style, rewritten)


def rewrite_preview_response(
    body: bytes,
    content_type: str,
    content_encoding: str,
    proxy_prefix: str,
    *,
    owner_seed: dict[str, Any] | None = None,
) -> tuple[bytes, bool]:
    """Rewrite same-origin root assets in a bounded textual Preview body."""

    if not body or content_encoding.strip().casefold() not in {"", "identity"}:
        return body, False
    mime = content_type.partition(";")[0].strip().casefold()
    if mime in {"text/html", "application/xhtml+xml"}:
        def rewrite(text: str, prefix: str) -> str:
            return _rewrite_preview_html(text, prefix, owner_seed=owner_seed)
    elif mime in {
        "application/javascript",
        "application/ecmascript",
        "application/typescript",
        "application/x-javascript",
        "text/javascript",
        "text/ecmascript",
        "text/typescript",
    }:
        rewrite = _rewrite_preview_javascript
    elif mime == "text/css":
        rewrite = _rewrite_preview_css
    else:
        return body, False

    charset_match = re.search(r"(?:^|;)\s*charset\s*=\s*['\"]?([^;'\"\s]+)", content_type, re.I)
    charset = charset_match.group(1) if charset_match else "utf-8"
    try:
        original = body.decode(charset)
        rewritten = rewrite(original, proxy_prefix)
        encoded = rewritten.encode(charset)
    except (LookupError, UnicodeError):
        return body, False
    return (encoded, True) if encoded != body else (body, False)


def decode_preview_content_encoding(body: bytes, content_encoding: str) -> tuple[bytes, bool]:
    """Boundedly decode the encodings a local Python gateway can guarantee."""

    encoding = content_encoding.strip().casefold()
    if not body or encoding in {"", "identity"}:
        return body, False
    if encoding in {"gzip", "x-gzip"}:
        window_bits = zlib.MAX_WBITS | 16
    elif encoding == "deflate":
        window_bits = zlib.MAX_WBITS
    else:
        # In practice the relay requests identity.  If an upstream ignores it
        # and returns an unsupported encoding such as br, preserve that body
        # and header rather than risk corrupting executable content.
        return body, False

    def decompress(bits: int) -> bytes:
        decoder = zlib.decompressobj(bits)
        decoded = decoder.decompress(body, MAX_PREVIEW_RESPONSE_BYTES + 1)
        if len(decoded) > MAX_PREVIEW_RESPONSE_BYTES or decoder.unconsumed_tail:
            raise ValueError("decoded Preview response is too large")
        remaining = MAX_PREVIEW_RESPONSE_BYTES + 1 - len(decoded)
        decoded += decoder.flush(remaining)
        if len(decoded) > MAX_PREVIEW_RESPONSE_BYTES or not decoder.eof:
            raise ValueError("invalid or oversized encoded Preview response")
        return decoded

    try:
        return decompress(window_bits), True
    except zlib.error:
        if encoding != "deflate":
            raise ValueError("invalid encoded Preview response")
        try:
            return decompress(-zlib.MAX_WBITS), True
        except zlib.error as exc:
            raise ValueError("invalid encoded Preview response") from exc


