def preview_static_cacheable(status: int, content_type: str) -> bool:
    mime = content_type.partition(";")[0].strip().casefold()
    return int(status) == int(HTTPStatus.OK) and (
        mime in _PREVIEW_CACHEABLE_STATIC_MIMES
        or mime.startswith("image/")
        or mime.startswith("audio/")
        or mime.startswith("video/")
    )


def preview_target_looks_static(target: str) -> bool:
    try:
        suffix = Path(urllib.parse.urlsplit(target).path).suffix.casefold()
    except ValueError:
        return False
    return suffix in _PREVIEW_STATIC_PATH_SUFFIXES


