    @staticmethod
    def _redact_operations_text(value: Any, *, limit: int = 1_000) -> str:
        """Return a short, credential-free excerpt safe to persist in public app state."""

        text = developer_visible_text(value)
        if not text:
            return ""
        text = re.sub(
            r"(?i)\b(api[_ -]?key|access[_ -]?token|refresh[_ -]?token|secret|password|passwd|authorization|"
            r"user[_ -]?id|device[_ -]?id|advertising[_ -]?id|precise[_ -]?location|ip(?:[_ -]?address)?)"
            r"\s*[:=]\s*[^\s,;]+",
            lambda match: f"{match.group(1)}=[REDACTED]",
            text,
        )
        text = re.sub(r"(?<![\w.+-])[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}(?![\w.-])", "[EMAIL]", text)
        text = re.sub(r"(?<!\d)(?:\+?86[- ]?)?1[3-9]\d{9}(?!\d)", "[PHONE]", text)
        text = re.sub(r"(?<!\d)(?:\d{1,3}\.){3}\d{1,3}(?!\d)", "[IP]", text)

        def clean_url(match: re.Match[str]) -> str:
            raw_url = match.group(0).rstrip(".,;，。；)")
            try:
                parsed = urllib.parse.urlsplit(raw_url)
            except ValueError:
                return "[URL]"
            if parsed.username or parsed.password:
                return "[URL]"
            return urllib.parse.urlunsplit((parsed.scheme, parsed.netloc, parsed.path, "", ""))

        text = re.sub(r"https?://[^\s<>\"']+", clean_url, text)
        return text[:limit]

    @staticmethod
    def _default_traffic_state() -> dict[str, Any]:
        return {
            "status": "not_configured",
            "summary": "",
            "platforms": [],
            "updated_at": "",
        }

    @classmethod
    def _normalize_traffic_state(cls, value: Any) -> dict[str, Any]:
        raw = value if isinstance(value, dict) else {}
        status = str(raw.get("status") or "not_configured").strip().casefold()
        allowed_statuses = {
            "not_configured", "draft", "scheduled", "running", "paused", "completed", "error",
        }
        if status not in allowed_statuses:
            status = "not_configured"
        platforms: list[dict[str, Any]] = []
        raw_platforms = raw.get("platforms")
        if isinstance(raw_platforms, list):
            for item in raw_platforms[:12]:
                if not isinstance(item, dict):
                    continue
                name = developer_visible_text(item.get("name"))[:120]
                if not name:
                    continue
                platforms.append({
                    "name": name,
                    "method": cls._redact_operations_text(item.get("method"), limit=240),
                    "schedule": cls._redact_operations_text(item.get("schedule"), limit=240),
                    "triggers": cls._redact_operations_text(item.get("triggers"), limit=240),
                    "status": str(item.get("status") or "draft").strip().casefold()[:32] or "draft",
                })
        return {
            "status": status,
            "summary": cls._redact_operations_text(raw.get("summary"), limit=500),
            "platforms": platforms,
            "updated_at": developer_visible_text(raw.get("updated_at"))[:64],
        }

    @classmethod
    def _mirror_legacy_operations_skill(cls, model: dict[str, Any]) -> None:
        analytics = model.get("analytics_skill")
        if isinstance(analytics, dict):
            model["operations_skill"] = json.loads(json.dumps(analytics, ensure_ascii=False))

